import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百四十九章 从痛苦中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/249第二百四十九章 从痛苦中解脱出来.md","filePath":"meditation/巴利文大藏经/249第二百四十九章 从痛苦中解脱出来.md"}'),r={name:"meditation/巴利文大藏经/249第二百四十九章 从痛苦中解脱出来.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百四十九章-从痛苦中解脱出来",tabindex:"-1"},[l("第二百四十九章 从痛苦中解脱出来 "),e("a",{class:"header-anchor",href:"#第二百四十九章-从痛苦中解脱出来","aria-label":'Permalink to "第二百四十九章 从痛苦中解脱出来"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应39经/随法经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！什么样的修人才是真正按着如来的正法循序渐进修行的人呢？",-1),e("p",null,"比丘们！那些精进努力去除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断贪欲、渴爱的修行人；那些不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断的修行人，他们就是真正按着如来的正法循序渐进修行的人。",-1),e("p",null,"当这些修行人，他们精进努力的去除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断贪欲、渴爱的时候，当这些修行人，他们不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断的时候，他们就不会被物质事物、物质身体、感受、念想、行为、认识、分别、判断束缚捆绑，他们就不会因为物质事物、物质身体、感受、念想、行为、认识、分别、判断而生起无数的念想，他们就能熄灭、除灭由物质事物、物质身体、感受、念想、行为、认识、分别、判断而产生的一切烦恼和痛苦，他们就能让内心保持长久的清净安宁，他们就能开启解脱的智慧，证悟解脱的果位。",-1),e("p",null,"当他们开启了解脱的智慧，当他们明白物质事物、物质身体、感受、念想、行为、认识、分别、判断是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的，那么他们就能最终从物质事物、物质身体、感受、念想、行为、认识、分别、判断中彻底的解脱出来，就能从忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡中彻底的解脱出来，他们就能除灭由物质事物、物质身体、感受、念想、行为、认识、分别、判断产生的一切烦恼和痛苦，从生死轮回中永远的解脱出来，他们就能证悟解脱的果位，达到不生不灭的涅槃境界。如来就说这些修行人：「他们已经永远从烦恼和痛苦中解脱出来。」 ”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
